14	/**
15	 * Assigns a newly created owner the unified {@code memberId} formatted
16	 * {@code '<REGION><FY><HASH8><CHK>'} (no separators): REGION is the region code derived from the
17	 * owner's postcode (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099, otherwise {@code UNKNOWN}); FY is
18	 * the two-digit fiscal year of the (business-day-adjusted) registrationDate (the fiscal year
19	 * starting 1 July); HASH8 is the first eight UPPER-case hex characters of the SHA-256 digest over
20	 * the normalized (E.164) telephone concatenated with the owner's last name — the same HASH8 used by
21	 * the region-and-hash identity; and CHK is a single Luhn check digit computed over the digits of
22	 * {@code <REGION><FY><HASH8>}. This unifies the former customerCode, membershipNumber and standalone
23	 * checkDigit into one identifier.
24	 *
25	 * <p>Mutates the {@link Owner} in place so it is persisted and returned with the memberId, and so
26	 * every value derived from it (audit line, owner segment, locality) reflects the new identity.
27	 *
28	 * <p>When the computed memberId collides with an existing owner's {@code memberId}, it is
29	 * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it
30	 * unique, so distinct owners always receive distinct memberIds.
31	 */
32	public class AssignOwnerMemberId {
33	
34	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
35	        String region = PostcodeRegions.regionForPostcode(owner.getPostcode());
36	        if (region == null) {
37	            region = "UNKNOWN";
38	        }
39	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
40	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
41	        String fy = owner.getRegistrationDate() == null ? "00"
42	                : String.format("%02d", OwnerMapper.fiscalYearOf(owner.getRegistrationDate()) % 100);
43	        String base = region + fy + hash8(telephone + lastName);
44	        String memberId = base + luhn(base);
45	        owner.setMemberId(deduplicate(memberId, owner, ownerRepository));
46	    }
47	
48	    /**
49	     * Return {@code base} if no existing owner already holds it, otherwise
50	     * {@code base + "-" + n} with the smallest {@code n >= 2} that is unused.
51	     */
52	    private static String deduplicate(String base, Owner owner, OwnerRepository ownerRepository) {
53	        Set<String> taken = new HashSet<>();
54	        for (Owner existing : ownerRepository.findAll()) {
55	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
56	                continue; // never collide with the owner itself
57	            }
58	            if (existing.getMemberId() != null) {
59	                taken.add(existing.getMemberId());
60	            }
61	        }
62	        if (!taken.contains(base)) {
63	            return base;
64	        }
65	        int n = 2;
66	        while (taken.contains(base + "-" + n)) {
67	            n++;
68	        }
69	        return base + "-" + n;
70	    }
71	
72	    /** Single Luhn check digit (0-9) over the digits contained in {@code value}. */
73	    private static int luhn(String value) {
74	        int sum = 0;
75	        boolean dbl = true;
76	        for (int i = value.length() - 1; i >= 0; i--) {
77	            char c = value.charAt(i);
78	            if (c < '0' || c > '9') {
79	                continue;
80	            }
81	            int d = c - '0';
82	            if (dbl) {
83	                d *= 2;
84	                if (d > 9) {
85	                    d -= 9;
86	                }
87	            }
88	            sum += d;
89	            dbl = !dbl;
90	        }
91	        return (10 - (sum % 10)) % 10;
92	    }
93	
94	    /** First eight UPPER-case hex characters (four bytes) of SHA-256 over the UTF-8 bytes. */
95	    private static String hash8(String value) {
96	        try {
97	            byte[] digest = MessageDigest.getInstance("SHA-256")
98	                    .digest(value.getBytes(StandardCharsets.UTF_8));
99	            StringBuilder sb = new StringBuilder(8);
100	            for (int i = 0; i < 4; i++) {
101	                sb.append(String.format("%02X", digest[i]));
102	            }
103	            return sb.toString();
104	        }
105	        catch (NoSuchAlgorithmException ex) {
106	            throw new IllegalStateException("SHA-256 not available", ex);
107	        }
108	    }
109	}
